ns.ProfRecipeKeys = KEYS
ns.ProfRecipes = setmetatable({}, {
    __index = function(t, k)
        local f = PARTS[k]
        if not f then return nil end
        PARTS[k] = nil
        local v = f()
        rawset(t, k, v)
        return v
    end,
})
ns.EnsureProfRecipes = function(keys)
    local t = ns.ProfRecipes
    local list = keys or KEYS
    for i = 1, #list do local _ = t[list[i]] end
    return t
end
